// Core animation library: 39 authored clips covering locomotion, air, flight, combat and
// reactions, written in canonical bone space and compiled against whatever rig is bound.
//
// HONESTY NOTE: these are hand-authored keyframe poses generated by this project. They are the
// documented FALLBACK library, not motion capture. When a licensed Mixamo/Sketchfab clip pack is
// installed under public/models/animations/, animation_loader.js loads those real clips and they
// replace the matching library entries at bind time. The manifest records which is which.
import * as THREE from 'three';
import { offsetQuaternion } from './rig_map.js';

export const LIBRARY_VERSION = 'browser-smash-animation-library-v1-20261022';

// Poses are Euler offsets (radians, XYZ) from the joint's bind rotation. Conventions verified
// against the prefab rig: negative X raises an arm/leg forward (+Z), positive X swings it back,
// left arm +Z and right arm -Z open outward, positive torso X leans forward.
