const _clipCache = new WeakMap();

/** Merge a clip key's pose delta over its stance so every key poses the whole body. */
export function poseAt(spec, index) {
  const stance = STANCES[spec.stance] || STANCES.ground;
  const delta = spec.keys[index]?.[1] || {};
  const out = {};
  for (const [bone, value] of Object.entries(stance)) out[bone] = value;
  for (const [bone, value] of Object.entries(delta)) out[bone] = value;
  return out;
}

function specToClip(id, spec, rig) {
  const keys = spec.keys;
  const duration = spec.duration || keys[keys.length - 1][0];
  const tracks = [];
  const bones = new Set();
  for (const [, pose] of keys) {
    const merged = { ...(STANCES[spec.stance] || STANCES.ground), ...pose };
    for (const bone of Object.keys(merged)) bones.add(bone);
  }
  const covered = [];
  for (const bone of bones) {
    if (!rig.joints[bone]) continue;
    covered.push(bone);
    const times = [];
    const values = [];
    for (let i = 0; i < keys.length; i++) {
      const pose = poseAt(spec, i);
      const euler = pose[bone] || [0, 0, 0];
      const quaternion = offsetQuaternion(rig, bone, euler);
      times.push(keys[i][0]);
      values.push(quaternion.x, quaternion.y, quaternion.z, quaternion.w);
    }
    tracks.push(new THREE.QuaternionKeyframeTrack(rig.joints[bone].name + '.quaternion', times, values));
  }
  const clip = new THREE.AnimationClip(id, duration, tracks);
  clip.userData = {
    id,
    label: spec.label,
    category: spec.category,
    loop: spec.loop !== false,
    clamp: Boolean(spec.clamp),
    priority: spec.priority || 1,
    peak: spec.peak ?? 0.5,
    origin: 'procedural',
    libraryVersion: LIBRARY_VERSION,
    bones: covered,
    missingBones: bones.size - covered.length
  };
  // Three.js plays clips through the mixer; keep the source spec for retiming/debugging.
  clip.userData.spec = { duration, stance: spec.stance, peak: spec.peak ?? 0.5 };
  return clip;
}

/**
 * Compile one library clip against a bound rig.
 * Clips are cached per rig because the baked quaternions depend on the rig's bind pose.
 */
export function buildClip(id, rig) {
  const spec = CLIP_SPECS[id];
  if (!spec || !rig) return null;
  let perRig = _clipCache.get(rig);
  if (!perRig) { perRig = new Map(); _clipCache.set(rig, perRig); }
  if (perRig.has(id)) return perRig.get(id);
  const clip = specToClip(id, spec, rig);
  perRig.set(id, clip);
  return clip;
}

/** Compile every library clip for a rig. Returns a Map of id -> AnimationClip. */
export function buildAllClips(rig) {
  const out = new Map();
  for (const id of Object.keys(CLIP_SPECS)) {
    const clip = buildClip(id, rig);
    if (clip) out.set(id, clip);
  }
  return out;
}

/**
 * Retime a one-shot clip so its strike peak lands on `peakAt` (0..1) of `duration`.
 * This is how an animation's active frames are made to match the gameplay hitbox window
 * exactly, without slowing the whole move down.
 */
export function retimeClip(clip, duration, peakAt = null) {
  const srcPeak = clip.userData?.peak ?? 0.5;
  const target = peakAt == null ? srcPeak : peakAt;
  const mapTime = t => {
    const srcDuration = clip.duration;
    const splitSrc = srcPeak * srcDuration;
    const splitDst = target * duration;
    if (t <= splitSrc) {
      if (splitSrc <= 1e-6) return 0;
      return (t / splitSrc) * splitDst;
    }
    const restSrc = srcDuration - splitSrc;
    if (restSrc <= 1e-6) return duration;
    return splitDst + ((t - splitSrc) / restSrc) * (duration - splitDst);
  };
  const tracks = clip.tracks.map(track => {
    const times = new Float32Array(track.times.length);
    for (let i = 0; i < track.times.length; i++) times[i] = mapTime(track.times[i]);
    return new track.constructor(track.name, times, track.values.slice());
  });
  const retimed = new THREE.AnimationClip(clip.name, duration, tracks);
  retimed.userData = { ...clip.userData, retimedFrom: clip.duration, peakAt: target };
  return retimed;
}

export function listClips() {
  return Object.entries(CLIP_SPECS).map(([id, spec]) => ({
    id,
    label: spec.label,
    category: spec.category,
    loop: spec.loop !== false,
    duration: spec.duration,
    priority: spec.priority || 1,
    peak: spec.peak ?? (spec.loop === false ? 0.5 : null)
  }));
}

/**
 * Sample an authored clip's pose at a normalised point (0..1) of its own timeline.
 *
 * The cinematic director needs the clip's real keyframes, not one frozen pose per beat: it drives the
 * body itself during an ultimate, so a static beat pose threw away the gather, the thrust and the
 * sustain that are the whole point of the authored move. Stance and keys are merged per bone exactly
 * as specToClip does, and adjacent keys are blended with a smoothstep so the sampled pose eases.
 */
export function sampleClipPose(id, fraction = 0) {
  const spec = CLIP_SPECS[id];
  if (!spec) return null;
  const keys = spec.keys;
  const duration = spec.duration || keys[keys.length - 1][0];
  const stance = STANCES[spec.stance] || STANCES.ground;
  const t = Math.min(1, Math.max(0, fraction)) * duration;
  let index = 0;
  while (index < keys.length - 2 && keys[index + 1][0] < t) index++;
  const [fromTime, fromPose] = keys[index];
  const [toTime, toPose] = keys[Math.min(index + 1, keys.length - 1)];
  const span = Math.max(1e-6, toTime - fromTime);
  const raw = Math.min(1, Math.max(0, (t - fromTime) / span));
  const weight = raw * raw * (3 - 2 * raw);
  const bones = new Set([...Object.keys(stance), ...Object.keys(fromPose), ...Object.keys(toPose)]);
  const out = {};
  for (const bone of bones) {
    const a = fromPose[bone] || stance[bone] || [0, 0, 0];
    const b = toPose[bone] || stance[bone] || [0, 0, 0];
    out[bone] = [
      a[0] + (b[0] - a[0]) * weight,
      a[1] + (b[1] - a[1]) * weight,
      a[2] + (b[2] - a[2]) * weight
    ];
  }
  return out;
}

export { STANCES };
